            JavaScript

    class FileSystemComponent {
    constructor() {}
    display() {
        throw new Error('Method not implemented.');
    }
}

class Directory extends FileSystemComponent {
    constructor(name) {
        super();
        this.name = name;
        this.components = [];
    }

    display() {
        console.log(`Directory: ${this.name}`);
        this.components.forEach(component => component.display());
    }

    addComponent(component) {
        this.components.push(component);
    }
}

Directory acts as a composite object that implements the FileSystemComponent interface and provides its own display method.It maintains a collection (vector) of FileSystemComponent objects to store files and subdirectories.The addComponent method allows adding child components, enabling a hierarchical file system structure.4. ClientThe Client code interacts with the components through the Component interface, and it doesn't need to be aware of whether it's working with a leaf or a composite object. 
            C++

    #include <iostream>
#include <vector>

class FileSystemComponent {
public:
    virtual void display() = 0;
};

class File : public FileSystemComponent {
private:
    std::string name;
    int size;
public:
    File(std::string name, int size) : name(name), size(size) {}
    void display() override {
        std::cout << "File: " << name << " Size: " << size << std::endl;
    }
};

class Directory : public FileSystemComponent {
private:
    std::string name;
    std::vector<FileSystemComponent*> components;
public:
    Directory(std::string name) : name(name) {}
    void addComponent(FileSystemComponent* component) {
        components.push_back(component);
    }
    void display() override {
        std::cout << "Directory: " << name << std::endl;
        for (auto component : components) {
            component->display();
        }
    }
};

int main() {
    // Create leaf objects (files)
    FileSystemComponent* file1 = new File("document.txt", 1024);
    FileSystemComponent* file2 = new File("image.jpg", 2048);

    // Create a composite object (directory)
    Directory directory("My Documents");

    // Add leaf objects to the directory
    directory.addComponent(file1);
    directory.addComponent(file2);

    // Display the directory (including its contents)
    directory.display();

    // Clean up
    delete file1;
    delete file2;
    return 0;
}


            Java

    import java.util.ArrayList;

interface FileSystemComponent {
    void display();
}

class File implements FileSystemComponent {
    private String name;
    private int size;

    public File(String name, int size) {
        this.name = name;
        this.size = size;
    }

    @Override
    public void display() {
        System.out.println("File: " + name + " Size: " + size);
    }
}

class Directory implements FileSystemComponent {
    private String name;
    private ArrayList<FileSystemComponent> components;

    public Directory(String name) {
        this.name = name;
        this.components = new ArrayList<>();
    }

    public void addComponent(FileSystemComponent component) {
        components.add(component);
    }

    @Override
    public void display() {
        System.out.println("Directory: " + name);
        for (FileSystemComponent component : components) {
            component.display();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        // Create leaf objects (files)
        FileSystemComponent file1 = new File("document.txt", 1024);
        FileSystemComponent file2 = new File("image.jpg", 2048);

        // Create a composite object (directory)
        Directory directory = new Directory("My Documents");

        // Add leaf objects to the directory
        directory.addComponent(file1);
        directory.addComponent(file2);

        // Display the directory (including its contents)
        directory.display();
    }
}


